# Terraform Module for S3 + RDS + IAM

I'll provide a complete, production-ready Terraform module structure supporting dev/prod environments via `tfvars` files.

## Directory Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── terraform.tfvars
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

## Root Module

### `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

module "s3" {
  source = "./modules/s3"

  bucket_name              = var.bucket_name
  enable_versioning        = var.enable_versioning
  enable_encryption        = var.enable_encryption
  kms_key_id               = var.kms_key_id
  enable_replication       = var.enable_replication
  replication_region       = var.replication_region
  environment              = var.environment

  tags = local.common_tags
}

module "rds" {
  source = "./modules/rds"

  db_instance_identifier   = var.db_instance_identifier
  db_name                  = var.db_name
  db_username              = var.db_username
  db_password              = var.db_password
  instance_class           = var.db_instance_class
  allocated_storage        = var.db_allocated_storage
  enable_encryption        = var.enable_db_encryption
  kms_key_id               = var.db_kms_key_id
  multi_az                 = var.db_multi_az
  backup_retention_period  = var.db_backup_retention_period
  enable_deletion_protection = var.db_enable_deletion_protection
  environment              = var.environment
  vpc_security_group_ids   = var.db_security_group_ids
  db_subnet_group_name     = var.db_subnet_group_name

  tags = local.common_tags
}

module "iam" {
  source = "./modules/iam"

  role_name                = var.iam_role_name
  oidc_provider_arn        = var.oidc_provider_arn
  oidc_subject             = var.oidc_subject
  enable_oidc              = var.enable_oidc
  environment              = var.environment
  s3_bucket_arn            = module.s3.bucket_arn
  s3_bucket_name           = module.s3.bucket_name
  rds_resource_id          = module.rds.db_resource_id

  tags = local.common_tags
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    CreatedAt   = formatdate("YYYY-MM-DD", timestamp())
  }
}
```

### `variables.tf`

```hcl
variable "aws_region" {
  type        = string
  description = "AWS region"
}

variable "environment" {
  type        = string
  description = "Environment name (dev, prod)"
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

# S3 Variables
variable "bucket_name" {
  type        = string
  description = "S3 bucket name"
  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*[a-z0-9]$", var.bucket_name))
    error_message = "Bucket name must be valid S3 format."
  }
}

variable "enable_versioning" {
  type        = bool
  description = "Enable S3 versioning"
  default     = true
}

variable "enable_encryption" {
  type        = bool
  description = "Enable S3 server-side encryption"
  default     = true
}

variable "kms_key_id" {
  type        = string
  description = "KMS key ID for S3 encryption (optional; uses AES-256 if not set)"
  default     = null
}

variable "enable_replication" {
  type        = bool
  description = "Enable S3 cross-region replication (prod only)"
  default     = false
}

variable "replication_region" {
  type        = string
  description = "Replication destination region"
  default     = "us-west-2"
}

# RDS Variables
variable "db_instance_identifier" {
  type        = string
  description = "RDS instance identifier"
}

variable "db_name" {
  type        = string
  description = "Initial database name"
}

variable "db_username" {
  type        = string
  description = "Master username"
  sensitive   = true
}

variable "db_password" {
  type        = string
  description = "Master password"
  sensitive   = true
}

variable "db_instance_class" {
  type        = string
  description = "RDS instance class (e.g., db.t3.micro, db.t3.medium)"
}

variable "db_allocated_storage" {
  type        = number
  description = "Allocated storage in GB"
  default     = 20
}

variable "enable_db_encryption" {
  type        = bool
  description = "Enable RDS encryption at rest"
  default     = true
}

variable "db_kms_key_id" {
  type        = string
  description = "KMS key ID for RDS encryption (optional)"
  default     = null
}

variable "db_multi_az" {
  type        = bool
  description = "Enable Multi-AZ deployment"
  default     = false
}

variable "db_backup_retention_period" {
  type        = number
  description = "Backup retention period in days"
  default     = 7
  validation {
    condition     = var.db_backup_retention_period >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "db_enable_deletion_protection" {
  type        = bool
  description = "Enable deletion protection"
  default     = true
}

variable "db_security_group_ids" {
  type        = list(string)
  description = "Security group IDs for RDS"
  default     = []
}

variable "db_subnet_group_name" {
  type        = string
  description = "DB subnet group name"
  default     = null
}

# IAM Variables
variable "iam_role_name" {
  type        = string
  description = "IAM role name"
}

variable "enable_oidc" {
  type        = bool
  description = "Enable OIDC trust (for EKS service accounts)"
  default     = false
}

variable "oidc_provider_arn" {
  type        = string
  description = "OIDC provider ARN (EKS)"
  default     = null
}

variable "oidc_subject" {
  type        = string
  description = "OIDC subject (e.g., system:serviceaccount:default:my-app)"
  default     = null
}
```

### `outputs.tf`

```hcl
output "s3_bucket_name" {
  value       = module.s3.bucket_name
  description = "S3 bucket name"
}

output "s3_bucket_arn" {
  value       = module.s3.bucket_arn
  description = "S3 bucket ARN"
}

output "rds_endpoint" {
  value       = module.rds.db_endpoint
  description = "RDS database endpoint"
  sensitive   = true
}

output "rds_database_name" {
  value       = module.rds.db_name
  description = "RDS database name"
}

output "rds_resource_id" {
  value       = module.rds.db_resource_id
  description = "RDS resource ID"
}

output "iam_role_arn" {
  value       = module.iam.role_arn
  description = "IAM role ARN"
}

output "iam_role_name" {
  value       = module.iam.role_name
  description = "IAM role name"
}
```

