## Environment-Specific Variables

### `dev.tfvars`

```hcl
aws_region             = "us-east-1"
environment            = "dev"

# S3
bucket_name            = "myapp-assets-dev-001"
enable_versioning      = true
enable_encryption      = true
kms_key_id             = null  # Use AWS managed key (AES-256)
enable_replication     = false

# RDS
db_instance_identifier = "myapp-postgres-dev"
db_name                = "myappdb"
db_username            = "postgres"
db_password            = "changeme"  # Use Terraform Cloud/Local Variables in practice
db_instance_class      = "db.t3.micro"
db_allocated_storage   = 20
enable_db_encryption   = true
db_multi_az            = false
db_backup_retention_period = 7
db_enable_deletion_protection = true

# IAM
iam_role_name          = "myapp-service-dev"
enable_oidc            = false
```

### `prod.tfvars`

```hcl
aws_region             = "us-east-1"
environment            = "prod"

# S3
bucket_name            = "myapp-assets-prod-001"
enable_versioning      = true
enable_encryption      = true
kms_key_id             = null  # Set to KMS ARN for customer-managed key in production
enable_replication     = true
replication_region     = "us-west-2"

# RDS
db_instance_identifier = "myapp-postgres-prod"
db_name                = "myappdb"
db_username            = "postgres"
db_password            = "changeme"  # Use AWS Secrets Manager or Terraform Cloud sensitive variables
db_instance_class      = "db.t3.medium"
db_allocated_storage   = 100
enable_db_encryption   = true
db_multi_az            = true
db_backup_retention_period = 30
db_enable_deletion_protection = true

# IAM
iam_role_name          = "myapp-service-prod"
enable_oidc            = true
oidc_provider_arn      = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E"
oidc_subject           = "system:serviceaccount:default:myapp-service-account"
```

### `terraform.tfvars` (defaults)

```hcl
# Sensible defaults; override per environment with -var-file=dev.tfvars or prod.tfvars
db_backup_retention_period = 7
db_enable_deletion_protection = true
enable_encryption = true
enable_versioning = true
```

