### RDS Module: `modules/rds/main.tf`

```hcl
resource "aws_db_instance" "this" {
  identifier            = var.db_instance_identifier
  engine                = "postgres"
  engine_version        = "15.4"  # Adjust as needed
  instance_class        = var.instance_class
  allocated_storage     = var.allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = var.enable_encryption
  kms_key_id            = var.kms_key_id

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  multi_az               = var.multi_az
  publicly_accessible    = false
  deletion_protection    = var.enable_deletion_protection
  backup_retention_period = var.backup_retention_period
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:00-sun:05:00"

  vpc_security_group_ids = var.vpc_security_group_ids
  db_subnet_group_name   = var.db_subnet_group_name

  skip_final_snapshot              = false
  final_snapshot_identifier        = "${var.db_instance_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  copy_tags_to_snapshot            = true
  enable_cloudwatch_logs_exports   = ["postgresql"]
  performance_insights_enabled      = true
  performance_insights_retention_period = 7
  enable_iam_database_authentication = true

  tags = merge(
    var.tags,
    { Name = var.db_instance_identifier }
  )

  lifecycle {
    ignore_changes = [password]  # Manage password separately
  }
}

resource "aws_db_parameter_group" "this" {
  family = "postgres15"
  name   = "${var.db_instance_identifier}-params"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  tags = var.tags
}
```

